/* banner: the loud strip at the top of a page, toned like everything else that speaks. */
Weave.library.components.bannerParts = spec => Weave.library.composition.compact([Weave.library.components.display({ text: Weave.library.components.titleOf(spec) }), Weave.library.components.note({ text: Weave.library.components.noteOf(spec) }), Weave.library.components.actionRow(spec)]);
Weave.library.components.banner = spec => Weave.library.components.bannerBox({ children: Weave.library.components.bannerParts(spec), data: Weave.library.components.toneData(spec) });
Weave.library.components.rules.bannerBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.space, padding: Weave.library.components.vars.spaceWide, borderRadius: Weave.library.components.vars.radiusLarge, background: Weave.library.components.vars.accentSoft, color: Weave.library.components.vars.accentSoftInk, borderLeft: Weave.library.components.borders.accentLine };

/* rating: a score out of the one count the system keeps, drawn from the two glyphs it keeps beside it. */
Weave.library.components.starCount = 5;
Weave.library.components.stars = {};
Weave.library.components.stars.on = '★';
Weave.library.components.stars.off = '☆';
Weave.library.components.starGlyph = isFilled => Weave.library.control.either(Weave.library.composition.identity, () => Weave.library.components.stars.on, () => Weave.library.components.stars.off)(isFilled);
Weave.library.components.starFor = spec => index => Weave.library.components.icon({ glyph: Weave.library.components.starGlyph(index < spec.value) });
Weave.library.components.ratingTotal = spec => Weave.library.control.defaultTo(Weave.library.components.starCount)(spec.total);
Weave.library.components.ratingLabel = spec => String(spec.value) + Weave.library.components.ratingJoin + String(Weave.library.components.ratingTotal(spec));
Weave.library.components.ratingJoin = ' of ';
Weave.library.components.rating = spec => Weave.library.components.ratingBox({ children: Weave.library.composition.range(Weave.library.components.ratingTotal(spec)).map(Weave.library.components.starFor(spec)), aria: { label: Weave.library.components.ratingLabel(spec) } });
Weave.library.components.rules.ratingBox = { display: Weave.library.components.values.inlineFlex, gap: Weave.library.components.vars.spaceTight, color: Weave.library.components.vars.toneWarning, letterSpacing: Weave.library.components.vars.tracking };

/* chip: a tag you can take off again, for the filters a reader has already chosen. */
Weave.library.components.chipClose = spec => Weave.library.control.maybe(run => Weave.library.components.actionButton({ label: Weave.library.components.closeLabel, size: Weave.library.components.markNames.size.small, variant: Weave.library.components.quietVariant(), onAction: run }))(spec.onRemove);
Weave.library.components.quietVariant = () => Weave.library.composition.keys(Weave.library.components.variants)[1];
Weave.library.components.chipParts = spec => Weave.library.composition.compact([Weave.library.components.tag({ text: Weave.library.components.textOf(spec, Weave.library.components.textKey) }), Weave.library.components.chipClose(spec)]);
Weave.library.components.chip = spec => Weave.library.components.chipBox({ children: Weave.library.components.chipParts(spec), data: Weave.library.components.toneData(spec) });
Weave.library.components.rules.chipBox = { display: Weave.library.components.values.inlineFlex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.spaceTight, borderRadius: Weave.library.components.vars.radiusRound, border: Weave.library.components.borders.hairline, background: Weave.library.components.vars.surface };

/* timeline: what happened and when, one row each, the time held to one side of the rail. */
Weave.library.components.momentParts = row => [Weave.library.components.timestamp({ text: row.when }), Weave.library.components.fill({ children: Weave.library.components.twoLines(row) })];
Weave.library.components.momentOf = row => Weave.library.components.timelineRow({ children: Weave.library.components.momentParts(row), data: { key: row.key } });
Weave.library.components.timeline = spec => Weave.library.components.timelineList({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.momentOf) });
Weave.library.components.rules.timelineList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.space };
Weave.library.components.rules.timelineRow = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.start, gap: Weave.library.components.vars.space, paddingLeft: Weave.library.components.vars.space, borderLeft: Weave.library.components.borders.hairline };

/* cards, second wave: the header and footer a card grows when it carries more than a paragraph. */
Weave.library.components.rules.cardHead = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, justifyContent: Weave.library.components.values.between, gap: Weave.library.components.vars.space, paddingBottom: Weave.library.components.vars.space, borderBottom: Weave.library.components.borders.hairline };
Weave.library.components.rules.cardFoot = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, justifyContent: Weave.library.components.values.between, gap: Weave.library.components.vars.space, paddingTop: Weave.library.components.vars.space, borderTop: Weave.library.components.borders.hairline, color: Weave.library.components.vars.muted, fontSize: Weave.library.components.vars.fontSizeSmall };
Weave.library.components.rules.hint = { color: Weave.library.components.vars.muted, fontSize: Weave.library.components.vars.fontSizeSmall };
Weave.library.components.rules.trackRow = { display: Weave.library.components.values.flex, gap: Weave.library.components.vars.spaceLoose, overflowX: Weave.library.components.values.auto, scrollSnapType: Weave.library.components.values.snapX, paddingBottom: Weave.library.components.vars.spaceTight };

/* controls, third wave: the two fields every sign in screen needs, and the hint a field can carry. */
Weave.library.components.fieldHint = spec => Weave.library.control.maybe(words => Weave.library.components.hint({ text: words }))(spec.hint);
Weave.library.components.fieldItems = spec => Weave.library.composition.compact([Weave.library.components.fieldLabel(spec), Weave.library.components.control(spec), Weave.library.components.fieldHint(spec)]);
Weave.library.components.revealLabels = {};
Weave.library.components.revealLabels.shown = 'Hide';
Weave.library.components.revealLabels.hidden = 'Show';
Weave.library.components.revealLabel = spec => Weave.library.control.either(Weave.library.composition.identity, () => Weave.library.components.revealLabels.shown, () => Weave.library.components.revealLabels.hidden)(spec.shown);
Weave.library.components.passwordType = spec => Weave.library.control.either(Weave.library.composition.identity, () => Weave.library.elements.inputTypes.text, () => Weave.library.elements.inputTypes.password)(spec.shown);
Weave.library.components.passwordControl = spec => Weave.library.components.control(Weave.library.composition.merge(spec, { type: Weave.library.components.passwordType(spec) }));
Weave.library.components.revealButton = spec => Weave.library.control.maybe(run => Weave.library.components.actionButton({ label: Weave.library.components.revealLabel(spec), size: Weave.library.components.markNames.size.small, onAction: run }))(spec.onReveal);
Weave.library.components.passwordRow = spec => Weave.library.components.inputGroupBox({ children: Weave.library.composition.compact([Weave.library.components.passwordControl(spec), Weave.library.components.revealButton(spec)]) });
Weave.library.components.passwordParts = spec => Weave.library.composition.compact([Weave.library.components.fieldLabel(spec), Weave.library.components.passwordRow(spec), Weave.library.components.fieldHint(spec)]);
Weave.library.components.passwordField = spec => Weave.library.components.build(Weave.library.components.parts.label, 'passwordField', { children: Weave.library.components.passwordParts(spec) });
Weave.library.components.codeLength = 6;
Weave.library.components.codeHints = spec => ({ maxlength: String(Weave.library.control.defaultTo(Weave.library.components.codeLength)(spec.length)), inputmode: Weave.library.components.digits, autocomplete: Weave.library.components.oneTimeCode });
Weave.library.components.codeAttributes = spec => Weave.library.composition.mergeAll([Weave.library.components.namedAttribute(spec), { [Weave.library.browser.keywords.value]: spec.value }, Weave.library.components.codeHints(spec)]);
Weave.library.components.digits = 'numeric';
Weave.library.components.oneTimeCode = 'one-time-code';
Weave.library.components.codeEntry = spec => Weave.library.components.build(Weave.library.components.parts.entry, 'codeEntry', { attributes: Weave.library.components.codeAttributes(spec), onEdit: spec.onEdit, aria: Weave.library.components.labelAria(spec) });
Weave.library.components.codeParts = spec => Weave.library.composition.compact([Weave.library.components.fieldLabel(spec), Weave.library.components.codeEntry(spec), Weave.library.components.fieldHint(spec)]);
Weave.library.components.codeField = spec => Weave.library.components.build(Weave.library.components.parts.label, 'codeField', { children: Weave.library.components.codeParts(spec) });
Weave.library.components.rules.passwordField = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.codeField = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.codeEntry = { background: Weave.library.components.vars.surface, color: Weave.library.components.vars.ink, minHeight: Weave.library.components.vars.controlHeightLarge, padding: Weave.library.components.vars.padSnug, border: Weave.library.components.borders.hairline, borderRadius: Weave.library.components.vars.radiusSmall, fontFamily: Weave.library.components.vars.fontMono, fontSize: Weave.library.components.vars.fontSizeLarge, letterSpacing: Weave.library.components.vars.trackingCode, textAlign: Weave.library.components.values.center , maxWidth: Weave.library.components.values.full };
/* tones, second wave: every other class that can be handed a tone, and how each one spends it. */
Weave.library.components.toneRules.tag = Weave.library.components.toneSpends.outline;
Weave.library.components.toneRules.badge = Weave.library.components.toneSpends.fill;
Weave.library.components.toneRules.bannerBox = Weave.library.components.toneSpends.edge;
Weave.library.components.toneRules.chipBox = Weave.library.components.toneSpends.outline;
Weave.library.components.toneRules.spinnerMark = Weave.library.components.toneSpends.cap;
Weave.library.components.toneRules.timelineRow = Weave.library.components.toneSpends.edge;

/* states, second wave: the marks the new widgets answer to, each still one row against one class. */
Weave.library.components.stateRules.anchorHere = { name: Weave.library.components.interactive.anchor, state: Weave.library.components.stateNames.here, style: { textDecoration: Weave.library.components.values.underline } };

/* presets: a named palette, spent on the page or on one subtree, without writing a theme or a rule. */
Weave.library.components.presets = {};
Weave.library.components.presets.ocean = { accent: '#0e7490', accentSoft: '#cffafe', accentSoftInk: '#0b4f5e', radius: '10px' };
Weave.library.components.presets.forest = { accent: '#15803d', accentSoft: '#dcfce7', accentSoftInk: '#14532d', radius: '6px' };
Weave.library.components.presets.plum = { accent: '#7c3aed', accentSoft: '#ede9fe', accentSoftInk: '#4c1d95', radius: '14px' };
Weave.library.components.presets.ember = { accent: '#c2410c', accentSoft: '#ffedd5', accentSoftInk: '#7c2d12', radius: '4px' };
Weave.library.components.presetNames = Weave.library.components.nameTable(Weave.library.components.presets);
Weave.library.components.presetTokens = name => Weave.library.control.defaultTo({})(Weave.library.components.presets[name]);
Weave.library.components.applyPreset = name => element => Weave.library.components.applyTokens(Weave.library.components.presetTokens(name))(element);
Weave.library.components.usePreset = name => Weave.library.components.applyPreset(name)(Weave.library.browser.documentElement());

/* configure: the one way a page moves a token before the sheet is written, so no page edits the library. */
Weave.library.components.configure = overrides => Object.assign(Weave.library.components.tokens, overrides);

/* themes, second wave: two more rows, each still nothing but token overrides. */
Weave.library.components.themes.contrast = { ink: '#000000', muted: '#1f2937', edge: '#000000', surface: '#ffffff', sunken: '#f1f1f1', accent: '#0b3ea8', accentSoft: '#dbe6ff', accentSoftInk: '#062a75', shadow: '0 0 0 1px #000000', focusRing: '0 0 0 3px #0b3ea8' };
Weave.library.components.themes.dusk = { ink: '#f5e9d7', muted: '#b9a68c', edge: '#4a3b2c', surface: '#2f2519', sunken: '#241c14', accent: '#e0a458', accentInk: '#241c14', accentSoft: '#3b2d1c', accentSoftInk: '#f0c891', mediaWash: 'linear-gradient(145deg, #3b2d1c, #241c14)', shadow: '0 1px 2px rgba(0, 0, 0, 0.45)', shadowLifted: '0 10px 30px rgba(0, 0, 0, 0.55)', focusRing: '0 0 0 3px rgba(224, 164, 88, 0.45)' };

/* breakpoints, second wave: the wide viewport, and what the new pieces do on a narrow one. */
Weave.library.components.breakpoints.wide = Weave.library.browser.fromWidth(Weave.library.components.tokens.pageWidth);
Weave.library.components.mediaRules.roomier = { query: Weave.library.components.breakpoints.wide, rules: { page: { maxWidth: Weave.library.components.vars.wideWidth } }, marks: {} };
Weave.library.components.mediaRules.compact.rules.column = { gridColumn: Weave.library.components.vars.spanFull };
Weave.library.components.mediaRules.compact.marks.span = Weave.library.components.columnSpans.full;
Weave.library.components.mediaRules.compact.rules.navbarBox = { flexDirection: Weave.library.components.values.column, alignItems: Weave.library.components.values.start };
Weave.library.components.mediaRules.compact.rules.termsBox = { gridTemplateColumns: Weave.library.components.values.full };
Weave.library.components.mediaRules.calm.rules.spinnerMark = { animation: Weave.library.components.values.none };

/* charts, the arithmetic: a reading becomes a length exactly here, as a share of the box it is drawn in. */
Weave.library.components.chartShare = (value, top) => Weave.library.control.either(() => top > 0, () => Weave.library.composition.clamp(0, 1)(value / top), Weave.library.composition.zero)(top);
Weave.library.components.chartTop = values => Math.max(...values);
Weave.library.components.chartSum = values => values.reduce((carried, value) => carried + value, 0);
Weave.library.components.chartRound = share => Math.round(share * 1000) / 10;
Weave.library.components.chartLength = share => String(Weave.library.components.chartRound(share)) + Weave.library.components.values.percent;
Weave.library.components.valuesIn = spec => Weave.library.control.defaultTo([])(spec.values);
Weave.library.components.linesIn = spec => Weave.library.control.defaultTo([])(spec.lines);
Weave.library.components.labelsIn = spec => Weave.library.control.defaultTo([])(spec.labels);
Weave.library.components.kidsIn = spec => Weave.library.control.defaultTo([])(spec.children);
Weave.library.components.valueOfRow = row => row.value;
Weave.library.components.topOfItems = spec => Weave.library.components.chartTop(Weave.library.components.itemsOf(spec).map(Weave.library.components.valueOfRow));

/* charts, the plot: one polyline per series over a square view box, stretched to whatever box it is given. */
Weave.library.components.plotSpan = 100;
Weave.library.components.plotStep = count => Weave.library.components.plotSpan / Math.max(count - 1, 1);
Weave.library.components.plotAcross = (index, count) => index * Weave.library.components.plotStep(count);
Weave.library.components.plotUp = (value, top) => Weave.library.components.plotSpan - Weave.library.components.chartShare(value, top) * Weave.library.components.plotSpan;
Weave.library.components.pointJoin = ',';
Weave.library.components.pointAt = (count, top) => (value, index) => String(Weave.library.components.plotAcross(index, count)) + Weave.library.components.pointJoin + String(Weave.library.components.plotUp(value, top));
Weave.library.components.pointsText = (values, top) => values.map(Weave.library.components.pointAt(values.length, top)).join(Weave.library.browser.keywords.space);
Weave.library.components.plotFrame = () => [0, 0, Weave.library.components.plotSpan, Weave.library.components.plotSpan].join(Weave.library.browser.keywords.space);
Weave.library.components.plotAttributes = () => ({ viewBox: Weave.library.components.plotFrame(), preserveAspectRatio: Weave.library.components.values.none });
Weave.library.components.ringAttributes = () => ({ viewBox: Weave.library.components.plotFrame() });
Weave.library.components.chartCeiling = spec => Weave.library.components.chartTop(Weave.library.components.linesIn(spec).flatMap(Weave.library.components.valuesIn));
Weave.library.components.traceFor = spec => line => Weave.library.components.chartLine({ series: line.series, attributes: { points: Weave.library.components.pointsText(line.values, Weave.library.components.chartCeiling(spec)) } });
Weave.library.components.lineChart = spec => Weave.library.components.chartPlot({ children: Weave.library.components.linesIn(spec).map(Weave.library.components.traceFor(spec)), attributes: Weave.library.components.plotAttributes(), aria: Weave.library.components.labelAria(spec) });
Weave.library.components.sparkTrace = spec => Weave.library.components.chartLine({ series: spec.series, attributes: { points: Weave.library.components.pointsText(Weave.library.components.valuesIn(spec), Weave.library.components.chartTop(Weave.library.components.valuesIn(spec))) } });
Weave.library.components.sparkline = spec => Weave.library.components.sparkPlot({ children: [Weave.library.components.sparkTrace(spec)], attributes: Weave.library.components.plotAttributes(), aria: Weave.library.components.labelAria(spec) });

/* charts, the axis: the words under a plot, in the order the readings above them were given. */
Weave.library.components.axisTick = text => Weave.library.components.axisLabel({ text });
Weave.library.components.axis = spec => Weave.library.components.axisRow({ children: Weave.library.components.labelsIn(spec).map(Weave.library.components.axisTick) });

/* charts, the legend: one entry per series, and pressing an entry takes that series off the chart. */
Weave.library.components.legendLabel = item => Weave.library.components.hint({ text: item.label });
Weave.library.components.legendParts = item => [Weave.library.components.legendSwatch({ series: item.series }), Weave.library.components.legendLabel(item)];
Weave.library.components.legendPress = item => Weave.library.components.legendButton({ children: Weave.library.components.legendParts(item), onAction: item.onAction, aria: { selected: String(item.shown) } });
Weave.library.components.legendStill = item => Weave.library.components.legendFace({ children: Weave.library.components.legendParts(item) });
Weave.library.components.legendBody = item => Weave.library.control.either(Weave.library.predicates.isFunction, () => Weave.library.components.legendPress(item), () => Weave.library.components.legendStill(item))(item.onAction);
Weave.library.components.legendRow = item => Weave.library.components.legendItem({ children: [Weave.library.components.legendBody(item)], data: { key: item.key } });
Weave.library.components.legend = spec => Weave.library.components.legendList({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.legendRow) });

/* charts, the frame: a figure that carries its own heading, legend and caption, so no chart is a bare box. */
Weave.library.components.legendIn = spec => Weave.library.control.maybe(items => Weave.library.components.legend({ items }))(spec.legend);
Weave.library.components.chartTitle = spec => Weave.library.control.maybe(() => Weave.library.components.titleLine(spec))(spec.title);
Weave.library.components.chartHeadParts = spec => Weave.library.composition.compact([Weave.library.components.chartTitle(spec), Weave.library.components.legendIn(spec)]);
Weave.library.components.chartCrown = spec => Weave.library.control.either(() => Weave.library.components.chartHeadParts(spec).length, () => Weave.library.components.chartHead({ children: Weave.library.components.chartHeadParts(spec) }), Weave.library.composition.noop)(spec);
Weave.library.components.chartTail = spec => Weave.library.control.maybe(words => Weave.library.components.chartCaption({ text: words }))(spec.note);
Weave.library.components.chartParts = spec => Weave.library.composition.compact([Weave.library.components.chartCrown(spec)].concat(Weave.library.components.kidsIn(spec), [Weave.library.components.chartTail(spec)]));
Weave.library.components.chart = spec => Weave.library.components.chartBox({ children: Weave.library.components.chartParts(spec) });

/* charts, the bars: a column per reading, its top rounded, its number written above and its name below. */
Weave.library.components.barOf = top => item => Weave.library.components.chartBar({ series: item.series, styles: { height: Weave.library.components.chartLength(Weave.library.components.chartShare(item.value, top)) }, attributes: { title: item.reading } });
Weave.library.components.barNumber = item => Weave.library.control.maybe(words => Weave.library.components.barValue({ text: words }))(item.reading);
Weave.library.components.barParts = (top, item) => Weave.library.composition.compact([Weave.library.components.barNumber(item), Weave.library.components.barTrack({ children: [Weave.library.components.barOf(top)(item)] }), Weave.library.components.axisLabel({ text: item.label })]);
Weave.library.components.barOne = top => item => Weave.library.components.barColumn({ children: Weave.library.components.barParts(top, item) });
Weave.library.components.barChart = spec => Weave.library.components.barsRow({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.barOne(Weave.library.components.topOfItems(spec))), aria: Weave.library.components.labelAria(spec) });

/* charts, the ranks: the same reading lying down, for the list of names too long to stand up. */
Weave.library.components.rankBarOf = top => item => Weave.library.components.rankFill({ series: item.series, styles: { width: Weave.library.components.chartLength(Weave.library.components.chartShare(item.value, top)) } });
Weave.library.components.rankParts = (top, item) => [Weave.library.components.truncate({ text: item.label }), Weave.library.components.rankTrack({ children: [Weave.library.components.rankBarOf(top)(item)] }), Weave.library.components.hint({ text: item.reading })];
Weave.library.components.rankOne = top => item => Weave.library.components.rankRow({ children: Weave.library.components.rankParts(top, item) });
Weave.library.components.rankBars = spec => Weave.library.components.rankList({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.rankOne(Weave.library.components.topOfItems(spec))), aria: Weave.library.components.labelAria(spec) });

/* charts, the ring: a part against its whole at a glance, with the whole itself written in the middle. */
Weave.library.components.ringRadius = 40;
Weave.library.components.ringGap = 2;
Weave.library.components.ringMiddle = () => Weave.library.components.plotSpan / 2;
Weave.library.components.ringRound = () => 2 * Math.PI * Weave.library.components.ringRadius;
Weave.library.components.ringLength = share => Math.max(share * Weave.library.components.ringRound() - Weave.library.components.ringGap, 0);
Weave.library.components.ringDash = share => String(Weave.library.components.ringLength(share)) + Weave.library.components.pointJoin + String(Weave.library.components.ringRound());
Weave.library.components.ringShift = before => String(0 - before * Weave.library.components.ringRound());
Weave.library.components.ringShares = spec => Weave.library.components.itemsOf(spec).map(item => Weave.library.components.chartShare(item.value, Weave.library.components.chartSum(Weave.library.components.itemsOf(spec).map(Weave.library.components.valueOfRow))));
Weave.library.components.ringBefore = (shares, index) => Weave.library.components.chartSum(shares.slice(0, index));
Weave.library.components.ringPlace = () => ({ cx: Weave.library.components.ringMiddle(), cy: Weave.library.components.ringMiddle(), r: Weave.library.components.ringRadius });
Weave.library.components.ringStroke = (shares, index) => ({ strokeDasharray: Weave.library.components.ringDash(shares[index]), strokeDashoffset: Weave.library.components.ringShift(Weave.library.components.ringBefore(shares, index)) });
Weave.library.components.ringArc = shares => (item, index) => Weave.library.components.ringSegment({ series: item.series, attributes: Weave.library.components.ringPlace(), styles: Weave.library.components.ringStroke(shares, index), aria: { label: item.reading } });
Weave.library.components.ringFace = spec => Weave.library.components.ringPlot({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.ringArc(Weave.library.components.ringShares(spec))), attributes: Weave.library.components.ringAttributes() });
Weave.library.components.ringHeart = spec => Weave.library.components.ringCentre({ children: [Weave.library.components.value({ text: spec.reading }), Weave.library.components.hint({ text: spec.label })] });
Weave.library.components.donut = spec => Weave.library.components.ringBox({ children: [Weave.library.components.ringFace(spec), Weave.library.components.ringHeart(spec)], aria: Weave.library.components.labelAria(spec) });

/* charts, the heatmap: a cell per reading, its step taken from the ramp, with that ramp drawn beside it. */
Weave.library.components.cellsOf = row => Weave.library.control.defaultTo([])(row.cells);
Weave.library.components.heatTop = spec => Weave.library.components.chartTop(Weave.library.components.itemsOf(spec).flatMap(Weave.library.components.cellsOf).map(Weave.library.components.valueOfRow));
Weave.library.components.heatCellOf = top => cell => Weave.library.components.heatCell({ heat: Weave.library.components.heatAt(Weave.library.components.chartShare(cell.value, top)), attributes: { title: cell.reading }, aria: { label: cell.reading } });
Weave.library.components.heatLine = top => row => Weave.library.components.heatRow({ children: [Weave.library.components.axisLabel({ text: row.label })].concat(Weave.library.components.cellsOf(row).map(Weave.library.components.heatCellOf(top))) });
Weave.library.components.heatmap = spec => Weave.library.components.heatGrid({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.heatLine(Weave.library.components.heatTop(spec))), aria: Weave.library.components.labelAria(spec) });
Weave.library.components.heatChip = name => Weave.library.components.heatCell({ heat: name });
Weave.library.components.heatChips = () => Weave.library.components.heatOrder.map(Weave.library.components.heatChip);
Weave.library.components.heatScale = spec => Weave.library.components.heatKey({ children: [Weave.library.components.hint({ text: spec.least })].concat(Weave.library.components.heatChips(), [Weave.library.components.hint({ text: spec.most })]) });

/* charts, the trend: which way a reading moved, said with an arrow, a word and a status colour at once. */
Weave.library.components.trendGlyphs = {};
Weave.library.components.trendGlyphs.up = '▲';
Weave.library.components.trendGlyphs.down = '▼';
Weave.library.components.trendGlyphs.level = '▬';
Weave.library.components.trendNames = Weave.library.components.nameTable(Weave.library.components.trendGlyphs);
Weave.library.components.trendWay = spec => Weave.library.control.defaultTo(Weave.library.components.trendNames.level)(spec.direction);
Weave.library.components.trendGlyph = spec => Weave.library.components.trendGlyphs[Weave.library.components.trendWay(spec)];
Weave.library.components.trendParts = spec => [Weave.library.components.icon({ glyph: Weave.library.components.trendGlyph(spec) }), Weave.library.components.textOf(spec, Weave.library.components.textKey)];
Weave.library.components.trend = spec => Weave.library.components.trendMark({ children: Weave.library.components.trendParts(spec), tone: spec.tone, aria: Weave.library.components.labelAria(spec) });

/* charts, the look: one row per class the widgets above draw, each still nothing but token references. */
Weave.library.components.rules.chartBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.space, margin: Weave.library.components.values.zero };
Weave.library.components.rules.chartHead = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, justifyContent: Weave.library.components.values.between, gap: Weave.library.components.vars.space, flexWrap: Weave.library.components.values.wrap };
Weave.library.components.rules.chartCaption = { color: Weave.library.components.vars.muted, fontSize: Weave.library.components.vars.fontSizeSmall };
Weave.library.components.rules.legendList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexWrap: Weave.library.components.values.wrap, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.legendItem = { display: Weave.library.components.values.inlineFlex };
Weave.library.components.rules.legendFace = { display: Weave.library.components.values.inlineFlex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.legendButton = { display: Weave.library.components.values.inlineFlex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.spaceTight, border: Weave.library.components.borders.hairline, borderRadius: Weave.library.components.vars.radiusRound, background: Weave.library.components.vars.surface, cursor: Weave.library.components.values.pointer, fontFamily: Weave.library.components.vars.font, fontSize: Weave.library.components.vars.fontSizeSmall, color: Weave.library.components.vars.ink };
Weave.library.components.rules.legendSwatch = { width: Weave.library.components.vars.swatchSize, height: Weave.library.components.vars.swatchSize, borderRadius: Weave.library.components.vars.radiusSmall, background: Weave.library.components.values.inherited, flexShrink: Weave.library.components.values.zero };
Weave.library.components.rules.chartPlot = { display: Weave.library.components.values.block, width: Weave.library.components.values.full, height: Weave.library.components.vars.plotHeight, overflow: Weave.library.components.values.visible, borderBottom: Weave.library.components.borders.hairline };
Weave.library.components.rules.sparkPlot = { display: Weave.library.components.values.block, width: Weave.library.components.values.full, height: Weave.library.components.vars.sparkHeight, overflow: Weave.library.components.values.visible };
Weave.library.components.rules.chartLine = { fill: Weave.library.components.values.none, stroke: Weave.library.components.values.inherited, strokeWidth: Weave.library.components.vars.markWidth, strokeLinecap: Weave.library.components.values.round, strokeLinejoin: Weave.library.components.values.round, vectorEffect: Weave.library.components.values.crisp };
Weave.library.components.rules.axisRow = { display: Weave.library.components.values.flex, justifyContent: Weave.library.components.values.between, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.axisLabel = { color: Weave.library.components.vars.muted, fontSize: Weave.library.components.vars.fontSizeSmall, whiteSpace: Weave.library.components.values.nowrap };
Weave.library.components.rules.barsRow = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.end, gap: Weave.library.components.vars.markWidth, borderBottom: Weave.library.components.borders.hairline };
Weave.library.components.rules.barColumn = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, flexGrow: Weave.library.components.values.grow, flexBasis: Weave.library.components.values.zero, minWidth: Weave.library.components.values.zero };
Weave.library.components.rules.barTrack = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.end, width: Weave.library.components.values.full, height: Weave.library.components.vars.plotHeight };
Weave.library.components.rules.chartBar = { width: Weave.library.components.values.full, background: Weave.library.components.values.inherited, borderTopLeftRadius: Weave.library.components.vars.radiusSmall, borderTopRightRadius: Weave.library.components.vars.radiusSmall, minHeight: Weave.library.components.vars.markWidth };
Weave.library.components.rules.barValue = { fontSize: Weave.library.components.vars.fontSizeSmall, fontWeight: Weave.library.components.values.heavy, whiteSpace: Weave.library.components.values.nowrap };
Weave.library.components.rules.rankList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.rankRow = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.space };
Weave.library.components.rules.rankTrack = { flexGrow: Weave.library.components.values.grow, height: Weave.library.components.vars.swatchSize, background: Weave.library.components.vars.sunken, borderRadius: Weave.library.components.vars.radiusRound, overflow: Weave.library.components.values.clip };
Weave.library.components.rules.rankFill = { height: Weave.library.components.values.full, background: Weave.library.components.values.inherited, borderRadius: Weave.library.components.vars.radiusRound };
Weave.library.components.rules.ringBox = { position: Weave.library.components.values.relative, width: Weave.library.components.vars.ringSize, height: Weave.library.components.vars.ringSize, display: Weave.library.components.values.grid, placeItems: Weave.library.components.values.center };
Weave.library.components.rules.ringPlot = { position: Weave.library.components.values.absolute, width: Weave.library.components.values.full, height: Weave.library.components.values.full, transform: Weave.library.components.values.quarterTurn };
Weave.library.components.rules.ringSegment = { fill: Weave.library.components.values.none, stroke: Weave.library.components.values.inherited, strokeWidth: Weave.library.components.vars.ringWidth };
Weave.library.components.rules.ringCentre = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, alignItems: Weave.library.components.values.center, textAlign: Weave.library.components.values.center, zIndex: Weave.library.components.values.one };
Weave.library.components.rules.heatGrid = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.markWidth };
Weave.library.components.rules.heatRow = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.markWidth };
Weave.library.components.rules.heatCell = { flexGrow: Weave.library.components.values.grow, flexBasis: Weave.library.components.values.zero, height: Weave.library.components.vars.swatchSize, borderRadius: Weave.library.components.vars.radiusSmall, background: Weave.library.components.vars.sunken };
Weave.library.components.rules.heatKey = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight };
Weave.library.components.rules.trendMark = { display: Weave.library.components.values.inlineFlex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, fontSize: Weave.library.components.vars.fontSizeSmall, fontWeight: Weave.library.components.values.heavy };
Weave.library.components.toneRules.trendMark = Weave.library.components.toneSpends.ink;
Weave.library.components.stateRules.legendFocus = Weave.library.components.focusRule(Weave.library.components.classNames.legendButton);
Weave.library.components.stateRules.legendGone = { name: Weave.library.components.classNames.legendButton, state: Weave.library.components.stateNames.unchosen, style: { opacity: Weave.library.components.values.faded, textDecoration: Weave.library.components.values.struck } };
Weave.library.components.mediaRules.compact.rules.ringBox = { width: Weave.library.components.values.full };

/* prose: the column a page of writing is set in, so a handbook never chooses its own measure. */
Weave.library.components.rules.prose = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceLoose, maxWidth: Weave.library.components.vars.proseWidth };

/* callout: the aside a handbook leans on, toned like everything else that speaks, led by a glyph. */
Weave.library.components.calloutHead = spec => Weave.library.components.row({ children: Weave.library.composition.compact([Weave.library.components.mediaGlyph(spec), Weave.library.components.strong({ text: Weave.library.components.titleOf(spec) })]) });
Weave.library.components.calloutParts = spec => [Weave.library.components.calloutHead(spec)].concat(Weave.library.components.childrenOf(spec, Weave.library.components.bodyKey));
Weave.library.components.callout = spec => Weave.library.components.calloutBox({ children: Weave.library.components.calloutParts(spec), data: Weave.library.components.toneData(spec) });
Weave.library.components.rules.calloutBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.space, background: Weave.library.components.vars.surface, borderLeft: Weave.library.components.borders.quoteEdge, borderRadius: Weave.library.components.vars.radiusSmall };
Weave.library.components.toneRules.calloutBox = Weave.library.components.toneSpends.edge;

/* contents: the list of where a page goes, with the section being read marked as the current one. */
Weave.library.components.contentsHere = (spec, row) => ({ current: String(row.key === spec.active) });
Weave.library.components.contentsLink = spec => row => Weave.library.components.anchor({ text: row.label, attributes: Weave.library.components.hrefAttribute(row), onAction: row.onAction, aria: Weave.library.components.contentsHere(spec, row) });
Weave.library.components.contentsRow = spec => row => Weave.library.components.item({ children: [Weave.library.components.contentsLink(spec)(row)] });
Weave.library.components.contentsRows = spec => Weave.library.components.contentsList({ children: Weave.library.components.itemsOf(spec).map(Weave.library.components.contentsRow(spec)) });
Weave.library.components.contents = spec => Weave.library.components.contentsBox({ children: [Weave.library.components.sectionLabel({ text: Weave.library.components.titleOf(spec) }), Weave.library.components.contentsRows(spec)], aria: { label: Weave.library.components.titleOf(spec) } });
Weave.library.components.rules.contentsBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight, position: Weave.library.components.values.sticky, top: Weave.library.components.vars.space };
Weave.library.components.rules.contentsList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight };

/* codeListing: a block of code under its own numbers, with the file it came from written under it. */
Weave.library.components.codeNumberAt = index => Weave.library.components.codeNumber({ text: String(index + 1) });
Weave.library.components.codeLineOf = (text, index) => Weave.library.components.codeLine({ children: [Weave.library.components.codeNumberAt(index), Weave.library.components.codeText({ text })] });
Weave.library.components.codeCaption = spec => Weave.library.control.maybe(words => Weave.library.components.credit({ text: words }))(spec.caption);
Weave.library.components.codeBlock = spec => Weave.library.components.codeLines({ children: Weave.library.components.linesIn(spec).map(Weave.library.components.codeLineOf) });
Weave.library.components.codeListing = spec => Weave.library.components.codeListingBox({ children: Weave.library.composition.compact([Weave.library.components.codeBlock(spec), Weave.library.components.codeCaption(spec)]) });
Weave.library.components.rules.codeListingBox = { margin: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.space, background: Weave.library.components.vars.sunken, border: Weave.library.components.borders.hairline, borderRadius: Weave.library.components.vars.radius, overflowX: Weave.library.components.values.auto };
Weave.library.components.rules.codeLines = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column };
Weave.library.components.rules.codeLine = { display: Weave.library.components.values.flex, gap: Weave.library.components.vars.space, fontFamily: Weave.library.components.vars.fontMono, fontSize: Weave.library.components.vars.fontSizeSmall, whiteSpace: Weave.library.components.values.preWrap };
Weave.library.components.rules.codeNumber = { color: Weave.library.components.vars.muted, minWidth: Weave.library.components.vars.gutterWidth, textAlign: Weave.library.components.values.right, flexShrink: Weave.library.components.values.zero };
Weave.library.components.rules.codeText = { color: Weave.library.components.vars.ink, minWidth: Weave.library.components.values.zero };

/* pager: what came before this page and what comes after it, at the foot of the page it belongs to. */
Weave.library.components.pagerKeys = {};
Weave.library.components.pagerKeys.previous = 'previous';
Weave.library.components.pagerKeys.next = 'next';
Weave.library.components.pagerFill = () => Weave.library.components.pagerGap({});
Weave.library.components.pagerEnd = spec => key => Weave.library.control.either(() => Weave.library.predicates.isDefined(spec[key]), () => Weave.library.components.crumb(spec[key]), Weave.library.components.pagerFill)(spec);
Weave.library.components.pagerParts = spec => Weave.library.composition.values(Weave.library.components.pagerKeys).map(Weave.library.components.pagerEnd(spec));
Weave.library.components.pager = spec => Weave.library.components.pagerBox({ children: Weave.library.components.pagerParts(spec), aria: Weave.library.components.labelAria(spec) });
Weave.library.components.rules.pagerBox = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, justifyContent: Weave.library.components.values.between, gap: Weave.library.components.vars.space, paddingTop: Weave.library.components.vars.space, borderTop: Weave.library.components.borders.hairline };
Weave.library.components.rules.pagerGap = { flexGrow: Weave.library.components.values.grow };

/* diff: what a change did to a file, one line at a time, each line saying which of the three it is. */
Weave.library.components.diffSigns = {};
Weave.library.components.diffSigns.added = '+';
Weave.library.components.diffSigns.removed = '−';
Weave.library.components.diffSigns.same = ' ';
Weave.library.components.diffNumber = row => Weave.library.components.diffGutter({ text: String(row.line) });
Weave.library.components.diffSign = row => Weave.library.components.diffGutter({ text: Weave.library.components.diffSigns[row.kind] });
Weave.library.components.diffLine = row => Weave.library.components.diffRow({ children: [Weave.library.components.diffNumber(row), Weave.library.components.diffSign(row), Weave.library.components.diffText({ text: row.text })], edit: row.kind });
Weave.library.components.diffHead = spec => Weave.library.control.maybe(words => Weave.library.components.code({ text: words }))(spec.title);
Weave.library.components.diffBody = spec => Weave.library.components.diffList({ children: Weave.library.components.rowsOf(spec).map(Weave.library.components.diffLine) });
Weave.library.components.diff = spec => Weave.library.components.diffBox({ children: Weave.library.composition.compact([Weave.library.components.diffHead(spec), Weave.library.components.diffBody(spec)]), aria: Weave.library.components.labelAria(spec) });
Weave.library.components.rules.diffBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.space, background: Weave.library.components.vars.surface, border: Weave.library.components.borders.hairline, borderRadius: Weave.library.components.vars.radius, overflowX: Weave.library.components.values.auto };
Weave.library.components.rules.diffList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column };
Weave.library.components.rules.diffRow = { display: Weave.library.components.values.flex, gap: Weave.library.components.vars.space, paddingLeft: Weave.library.components.vars.spaceTight, borderLeft: Weave.library.components.borders.quoteEdge, fontFamily: Weave.library.components.vars.fontMono, fontSize: Weave.library.components.vars.fontSizeSmall, whiteSpace: Weave.library.components.values.preWrap };
Weave.library.components.rules.diffGutter = { color: Weave.library.components.vars.muted, minWidth: Weave.library.components.vars.gutterWidth, textAlign: Weave.library.components.values.right, flexShrink: Weave.library.components.values.zero };
Weave.library.components.rules.diffText = { color: Weave.library.components.vars.ink, minWidth: Weave.library.components.values.zero };

/* diffStat: how much a change added and how much it took away, the pair a file list is ranked by. */
Weave.library.components.diffCount = (sign, total) => sign + String(total);
Weave.library.components.diffAdded = spec => Weave.library.components.statAdded({ text: Weave.library.components.diffCount(Weave.library.components.diffSigns.added, spec.added) });
Weave.library.components.diffRemoved = spec => Weave.library.components.statRemoved({ text: Weave.library.components.diffCount(Weave.library.components.diffSigns.removed, spec.removed) });
Weave.library.components.diffStat = spec => Weave.library.components.diffStatBox({ children: [Weave.library.components.diffAdded(spec), Weave.library.components.diffRemoved(spec)] });
Weave.library.components.rules.diffStatBox = { display: Weave.library.components.values.inlineFlex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight, fontSize: Weave.library.components.vars.fontSizeSmall, fontWeight: Weave.library.components.values.heavy };
Weave.library.components.rules.statAdded = { color: Weave.library.components.vars.toneSuccess };
Weave.library.components.rules.statRemoved = { color: Weave.library.components.vars.toneDanger };

/* comment: one remark by one person, over the time they made it, with whatever they can do to it. */
Weave.library.components.commentHeadParts = spec => [Weave.library.components.portrait({ name: spec.name }), Weave.library.components.fill({ children: [Weave.library.components.strong({ text: spec.name })] }), Weave.library.components.timestamp({ text: spec.when })];
Weave.library.components.commentHeader = spec => Weave.library.components.commentHead({ children: Weave.library.components.commentHeadParts(spec) });
Weave.library.components.commentActions = spec => Weave.library.control.maybe(actions => Weave.library.components.actionBar({ actions }))(spec.actions);
Weave.library.components.commentParts = spec => Weave.library.composition.compact([Weave.library.components.commentHeader(spec), Weave.library.components.text({ text: Weave.library.components.textOf(spec, Weave.library.components.textKey) }), Weave.library.components.commentActions(spec)]);
Weave.library.components.comment = spec => Weave.library.components.commentBox({ children: Weave.library.components.commentParts(spec) });
Weave.library.components.rules.commentBox = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight, padding: Weave.library.components.vars.space, background: Weave.library.components.vars.surface, border: Weave.library.components.borders.hairline, borderRadius: Weave.library.components.vars.radius };
Weave.library.components.rules.commentHead = { display: Weave.library.components.values.flex, alignItems: Weave.library.components.values.center, gap: Weave.library.components.vars.spaceTight };

/* commentThread: the remarks in the order they were made, and the box a reader answers them in. */
Weave.library.components.threadOne = row => Weave.library.components.threadItem({ children: [Weave.library.components.comment(row)] });
Weave.library.components.threadReply = spec => Weave.library.control.maybe(children => Weave.library.components.threadItem({ children }))(spec.reply);
Weave.library.components.threadParts = spec => Weave.library.composition.compact(Weave.library.components.itemsOf(spec).map(Weave.library.components.threadOne).concat([Weave.library.components.threadReply(spec)]));
Weave.library.components.commentThread = spec => Weave.library.components.threadList({ children: Weave.library.components.threadParts(spec) });
Weave.library.components.rules.threadList = { listStyle: Weave.library.components.values.none, margin: Weave.library.components.values.zero, padding: Weave.library.components.values.zero, display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.space };
Weave.library.components.rules.threadItem = { display: Weave.library.components.values.flex, flexDirection: Weave.library.components.values.column, gap: Weave.library.components.vars.spaceTight };

/* dropzone: the one target a file can be dropped on, which marks itself while a file is over it. */
Weave.library.components.overKey = 'over';
Weave.library.components.dropMark = value => event => Weave.library.attributes.setData(Weave.library.components.overKey, value)(Weave.library.browser.currentTargetOf(event));
Weave.library.components.dropEnter = Weave.library.components.dropMark(Weave.library.browser.keywords.true);
Weave.library.components.dropLeave = Weave.library.components.dropMark(Weave.library.browser.keywords.false);
Weave.library.components.dropDone = spec => event => (Weave.library.components.dropLeave(event), Weave.library.control.maybe(run => run(event))(spec.onDrop));
Weave.library.components.dropOptions = spec => ({ onEnter: Weave.library.components.dropEnter, onLeave: Weave.library.components.dropLeave, onDrop: Weave.library.components.dropDone(spec) });
Weave.library.components.dropWiring = spec => element => Weave.library.interaction.droppable(Weave.library.components.dropOptions(spec))(element);
Weave.library.components.dropzoneWords = spec => [Weave.library.components.strong({ text: Weave.library.components.titleOf(spec) }), Weave.library.components.note({ text: Weave.library.components.noteOf(spec) })];
Weave.library.components.dropzoneParts = spec => Weave.library.composition.compact([Weave.library.components.mediaGlyph(spec)].concat(Weave.library.components.dropzoneWords(spec), [Weave.library.components.alertAction(spec)]));
